import * as React from "react";

import { useFieldControlAttributes } from "../lib/field-context";
import { cn } from "../lib/utils";
import { Button } from "./button";
import {
  Empty,
  EmptyContent,
  EmptyDescription,
  EmptyHeader,
  EmptyMedia,
  EmptyTitle
} from "./empty";
import { Icon, type IconSource } from "./icon";
import { Media } from "./item";
import { MiddleTruncate } from "./middle-truncate";

import styles from "./file-input.module.css";
import helperStyles from "./helpers.module.css";

const UNITS = ["B", "KB", "MB", "GB"];

export const formatFileSize = (bytes: number) => {
  let value = bytes;
  let unit = 0;
  while (value >= 1024 && unit < UNITS.length - 1) {
    value /= 1024;
    unit += 1;
  }
  const rounded = unit === 0 || value >= 10 ? Math.round(value) : Math.round(value * 10) / 10;
  return `${rounded} ${UNITS[unit]}`;
};

const acceptTokens = (accept?: string) =>
  (accept ?? "")
    .split(",")
    .map((token) => token.trim().toLowerCase())
    .filter(Boolean);

const matchesAccept = (file: File, tokens: string[]) => {
  if (!tokens.length) return true;
  const name = file.name.toLowerCase();
  const type = file.type.toLowerCase();
  return tokens.some((token) => {
    if (token.startsWith(".")) return name.endsWith(token);
    if (token.endsWith("/*")) return type.startsWith(token.slice(0, -1));
    return type === token;
  });
};

const typeLabel = (token: string) => {
  if (token.startsWith(".")) return token.slice(1).toUpperCase();
  const [group, subtype] = token.split("/");
  if (subtype === "*") return `${group.charAt(0).toUpperCase()}${group.slice(1)} files`;
  return (subtype ?? group).replace(/^x-|\+.*$/g, "").toUpperCase();
};

const listFormat = (items: string[]) =>
  items.length < 2 ? items.join("") : `${items.slice(0, -1).join(", ")} or ${items.at(-1)}`;

const MAX_LISTED_REJECTIONS = 3;

export type FileInputProps = {
  /** Selected files, listed under the zone. */
  files?: File[];
  /** Receives the files this pick or drop added that pass accept and maxSize. */
  onFiles: (files: File[]) => void;
  /** Renders a remove button on each listed file. */
  onRemove?: (file: File, index: number) => void;
  /** The native accept list: extensions (.json) and MIME types (image/png, image/*). Picked and dropped files are both checked against it. */
  accept?: string;
  multiple?: boolean;
  /** The largest file accepted, in bytes. */
  maxSize?: number;
  disabled?: boolean;
  /** A message from the caller, such as a file that failed to parse. Announced with the rejected files. */
  error?: string;
  title?: string;
  /** Replaces the accepted types and size line derived from accept and maxSize. */
  hint?: string;
  icon?: IconSource;
  size?: "default" | "sm";
  className?: string;
  id?: string;
  name?: string;
  "aria-label"?: string;
  "aria-labelledby"?: string;
  "aria-describedby"?: string;
};

/**
 * A drop target for files with a Browse button over a hidden native file input. Picked and dropped
 * files are filtered by accept and maxSize; the rest are named in a live region instead of added.
 */
export function FileInput({
  files,
  onFiles,
  onRemove,
  accept,
  multiple = false,
  maxSize,
  disabled = false,
  error,
  title,
  hint,
  icon = "upload",
  size = "default",
  className,
  name,
  ref,
  ...props
}: FileInputProps & { ref?: React.Ref<HTMLInputElement> }) {
  const field = useFieldControlAttributes(props);
  const generated = React.useId();
  const titleId = `${generated}-title`;
  const hintId = `${generated}-hint`;
  const messageId = `${generated}-message`;
  const input = React.useRef<HTMLInputElement>(null);
  const zone = React.useRef<HTMLDivElement>(null);
  React.useImperativeHandle(ref, () => input.current!, []);
  const [dragging, setDragging] = React.useState(false);
  const [rejected, setRejected] = React.useState<{ attempt: number; messages: string[] }>({
    attempt: 0,
    messages: []
  });
  const rejections = rejected.messages;
  const setRejections = (messages: string[]) =>
    setRejected((current) => ({ attempt: current.attempt + 1, messages }));
  // A disabled FieldSet disables the native input without passing disabled down.
  const locked = () => disabled || Boolean(input.current?.matches(":disabled"));
  const tokens = acceptTokens(accept);
  const noun = multiple ? "files" : "a file";
  const sizeLabel = maxSize === undefined ? undefined : formatFileSize(maxSize);
  const typesLabel = tokens.length ? listFormat([...new Set(tokens.map(typeLabel))]) : undefined;
  const derivedHint = [typesLabel, sizeLabel && `up to ${sizeLabel}`].filter(Boolean).join(", ");
  const hintText =
    hint ?? (derivedHint && derivedHint.charAt(0).toUpperCase() + derivedHint.slice(1));
  const invalid = Boolean(error || rejections.length || field["aria-invalid"]);
  const messages = [...(error ? [error] : []), ...rejections];

  const take = (list: File[]) => {
    if (locked() || !list.length) return;
    if (!multiple && list.length > 1) {
      setRejections(["Drop one file at a time."]);
      return;
    }
    const accepted: File[] = [];
    const rejected: string[] = [];
    for (const file of list) {
      if (!matchesAccept(file, tokens)) rejected.push(`${file.name} isn't a ${typesLabel} file.`);
      else if (maxSize !== undefined && file.size > maxSize)
        rejected.push(`${file.name} is larger than ${sizeLabel}.`);
      else accepted.push(file);
    }
    const hidden = rejected.length - MAX_LISTED_REJECTIONS;
    setRejections(
      hidden > 0
        ? [
            ...rejected.slice(0, MAX_LISTED_REJECTIONS),
            `${hidden} more ${hidden === 1 ? "file was" : "files were"} not added.`
          ]
        : rejected
    );
    if (accepted.length) onFiles(accepted);
  };

  const browse = () => {
    if (!locked()) input.current?.click();
  };

  const leaves = (event: React.DragEvent) =>
    !(event.relatedTarget instanceof Node && event.currentTarget.contains(event.relatedTarget));

  return (
    <div data-slot="file-input" data-size={size} className={cn(styles.root, className)}>
      <input
        ref={input}
        id={field.id}
        name={name}
        type="file"
        accept={accept}
        multiple={multiple}
        disabled={disabled}
        tabIndex={-1}
        hidden
        onChange={(event) => {
          take(Array.from(event.target.files ?? []));
          event.target.value = "";
        }}
      />
      <Empty
        ref={zone}
        size={size}
        role="button"
        tabIndex={disabled ? -1 : 0}
        aria-label={props["aria-label"]}
        aria-labelledby={
          props["aria-label"]
            ? undefined
            : [field["aria-labelledby"], titleId].filter(Boolean).join(" ")
        }
        aria-describedby={
          [
            hintText ? hintId : undefined,
            messages.length ? messageId : undefined,
            field["aria-describedby"]
          ]
            .filter(Boolean)
            .join(" ") || undefined
        }
        aria-disabled={disabled || undefined}
        aria-invalid={invalid || undefined}
        data-dragging={dragging || undefined}
        data-disabled={disabled || undefined}
        data-invalid={invalid || undefined}
        className={styles.zone}
        onClick={browse}
        onKeyDown={(event) => {
          if (event.target !== event.currentTarget) return;
          if (event.key !== "Enter" && event.key !== " ") return;
          event.preventDefault();
          browse();
        }}
        onDragEnter={(event) => {
          event.preventDefault();
          if (!locked()) setDragging(true);
        }}
        onDragOver={(event) => {
          event.preventDefault();
          event.dataTransfer.dropEffect = locked() ? "none" : "copy";
        }}
        onDragLeave={(event) => {
          if (leaves(event)) setDragging(false);
        }}
        onDrop={(event) => {
          event.preventDefault();
          setDragging(false);
          take(Array.from(event.dataTransfer.files));
        }}
      >
        <EmptyMedia>
          <Icon icon={icon} />
        </EmptyMedia>
        <EmptyHeader>
          <EmptyTitle id={titleId}>
            {dragging
              ? `Drop to add ${multiple ? "the files" : "the file"}`
              : (title ?? `Drop ${noun} or browse`)}
          </EmptyTitle>
          {hintText && <EmptyDescription id={hintId}>{hintText}</EmptyDescription>}
        </EmptyHeader>
        <EmptyContent>
          <Button asChild variant="outline" size={size === "sm" ? "xs" : "default"}>
            <span aria-hidden="true">Browse</span>
          </Button>
        </EmptyContent>
      </Empty>
      <div id={messageId} aria-live="polite" className={styles.messages}>
        {messages.map((message, index) => (
          <p key={`${rejected.attempt}-${index}`} className={helperStyles.fieldError}>
            <Icon name="alert" size={14} />
            <span>{message}</span>
          </p>
        ))}
      </div>
      {Boolean(files?.length) && (
        <ul className={styles.list} aria-label={multiple ? "Selected files" : "Selected file"}>
          {files!.map((file, index) => (
            <li key={`${file.name}-${index}`} className={styles.file}>
              <Media icon="file" size="sm" />
              <MiddleTruncate
                className={styles.name}
                keepEnd={
                  file.name.lastIndexOf(".") > 0
                    ? Math.max(8, file.name.length - file.name.lastIndexOf("."))
                    : 8
                }
              >
                {file.name}
              </MiddleTruncate>
              <span className={styles.size}>{formatFileSize(file.size)}</span>
              {onRemove && (
                <Button
                  type="button"
                  variant="ghost"
                  size="icon-xs"
                  icon="x"
                  iconOnly
                  disabled={disabled}
                  onClick={() => {
                    onRemove(file, index);
                    zone.current?.focus();
                  }}
                >{`Remove ${file.name}`}</Button>
              )}
            </li>
          ))}
        </ul>
      )}
    </div>
  );
}
FileInput.displayName = "FileInput";

.root {
  display: flex;
  width: 100%;
  min-width: 0;
  flex-direction: column;
}
.zone {
  border: var(--cipher-size-control-border) dashed var(--cipher-line);
  background: var(--cipher-tint);
  cursor: pointer;
  transition:
    background-color var(--cipher-duration-fast) var(--cipher-ease-standard),
    border-color var(--cipher-duration-fast) var(--cipher-ease-standard);
}
.zone:hover:not([data-disabled]) {
  background: var(--cipher-hover);
}
.zone:focus-visible {
  outline: var(--cipher-size-focus-ring) solid var(--cipher-ink);
  outline-offset: var(--cipher-size-focus-ring);
}
.zone[data-invalid] {
  border-color: var(--cipher-control-invalid-border);
}
.zone[data-dragging] {
  border-style: solid;
  border-color: var(--cipher-accent-line);
  background: var(--cipher-accent-wash);
}
.zone[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.messages {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
}
.messages > p > span {
  min-width: 0;
  overflow-wrap: anywhere;
}
.messages:not(:empty) {
  margin-block-start: var(--cipher-space-8);
}
.list {
  display: flex;
  min-width: 0;
  flex-direction: column;
  gap: var(--cipher-space-4);
  margin: var(--cipher-space-8) 0 0;
  padding: 0;
  list-style: none;
}
.file {
  display: flex;
  min-width: 0;
  align-items: center;
  gap: var(--cipher-space-8);
}
.name {
  flex: 1;
  min-width: 0;
  color: var(--cipher-ink);
}
.size {
  flex-shrink: 0;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
}

.avatarFallback {
  background: var(--cipher-tint);
  color: var(--cipher-ink);
  font-family: var(--cipher-type-label-font-family);
  font-weight: var(--cipher-type-label-font-weight);
  line-height: 1;
  letter-spacing: 0;
}
.avatarFallback svg {
  width: 50%;
  height: 50%;
  max-width: var(--cipher-size-icon);
  max-height: var(--cipher-size-icon);
}
.count {
  font-family: var(--cipher-type-mono-sm-font-family);
  font-size: var(--cipher-type-mono-sm-font-size);
  line-height: var(--cipher-type-mono-sm-line-height);
  font-weight: var(--cipher-type-mono-sm-font-weight);
  letter-spacing: var(--cipher-type-mono-sm-letter-spacing);
  display: inline-flex;
  min-width: var(--cipher-size-count);
  height: var(--cipher-size-count);
  padding: 0 var(--cipher-space-4);
  align-items: center;
  justify-content: center;
  border-radius: 0;
  background: var(--cipher-accent);
  color: var(--cipher-on-accent);
}
.countInk {
  background: var(--cipher-ink);
  color: var(--cipher-surface);
}
.countNeutral {
  background: var(--cipher-tint);
  color: var(--cipher-text2);
}
.count[data-tone="warn"] {
  background: var(--cipher-warn-bg);
  color: var(--cipher-warn);
}
.count[data-tone="bad"] {
  background: var(--cipher-bad-bg);
  color: var(--cipher-bad);
}
.identity {
  display: flex;
  align-items: center;
  gap: 8px;
  min-width: 0;
}
.identityText {
  flex: 1 1 auto;
  min-width: 0;
  display: flex;
  flex-direction: column;
  gap: 2px;
}
.identityTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.identityDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  color: var(--cipher-text2, var(--muted-foreground));
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}
.mono {
  font-family: var(--cipher-font-mono, monospace);
}
.media {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 40px;
  height: 40px;
  flex: 0 0 auto;
  color: var(--cipher-ink, var(--foreground));
  background: var(--cipher-surface);
  border: var(--cipher-size-control-border) solid var(--cipher-line-soft);
  border-radius: 0;
}
.mediaSmall {
  width: 24px;
  height: 24px;
}
.tile {
  display: flex;
  box-sizing: border-box;
  text-decoration: none;
  align-items: center;
  gap: 12px;
  width: 100%;
  padding: var(--cipher-space-12);
  text-align: start;
  border: 1px solid var(--cipher-line-soft, var(--border));
  background: var(--cipher-surface, var(--background));
  color: var(--cipher-ink, var(--foreground));
}
.tile:not([aria-disabled="true"]):hover {
  border-color: var(--cipher-control, var(--border));
  background: var(--cipher-hover);
}
.tile[data-in-frame] {
  border-color: transparent;
  background: var(--cipher-tint);
}
.tile[data-in-frame]:not([aria-disabled="true"]):hover {
  background: color-mix(in srgb, var(--cipher-mix-ink) var(--cipher-hover-mix), var(--cipher-tint));
}
.tile[aria-pressed="true"],
.tile[aria-current="page"] {
  border-color: var(--cipher-ink, var(--foreground));
}
.tile:disabled,
.tile[data-disabled] {
  cursor: not-allowed;
  opacity: 0.5;
}
.tile:focus-visible {
  outline: 2px solid var(--ring, var(--ring));
  outline-offset: 2px;
}
.tileBody {
  flex: 1;
  min-width: 0;
}
.tile:not([data-layout="stacked"]) {
  flex-wrap: wrap;
  align-content: flex-start;
  align-items: flex-start;
}
.tile:not([data-layout="stacked"]) > .tileBody,
.tile:not([data-layout="stacked"]) > svg:last-child {
  align-self: center;
}
.tile[aria-disabled="true"] {
  cursor: not-allowed;
}
.tile[data-layout="stacked"] {
  flex-direction: column;
  align-items: stretch;
  gap: var(--cipher-space-4);
  padding: var(--cipher-space-16);
}
.tile[data-layout="stacked"] > .tileBody {
  flex: 1 1 auto;
}
.tileTop {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: var(--cipher-space-12);
  min-width: 0;
  margin-bottom: var(--cipher-space-8);
}
.tileAside {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  min-width: 0;
  margin-inline-start: auto;
  color: var(--cipher-muted);
}
.tileAside > :not(.tileEyebrow) {
  flex: none;
}
.tileEyebrow {
  min-width: 0;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: var(--cipher-muted);
  font-family: var(--cipher-type-eyebrow-font-family);
  font-size: var(--cipher-type-eyebrow-font-size);
  line-height: var(--cipher-type-eyebrow-line-height);
  font-weight: var(--cipher-type-eyebrow-font-weight);
  letter-spacing: var(--cipher-type-eyebrow-letter-spacing);
  text-transform: uppercase;
}
.tile[aria-disabled="true"]:not([data-disabled]) > .tileTop {
  opacity: 0.5;
}
.banner {
  display: flex;
  width: 100%;
  align-items: center;
  flex-wrap: wrap;
  gap: 12px;
  border: 1px solid var(--cipher-accent-line);
  background: var(--cipher-accent-wash);
  color: var(--cipher-ink, var(--foreground));
  padding: 10px 16px;
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
}
.bannerLead {
  display: flex;
  flex: 1;
  align-items: flex-start;
  gap: 12px;
  min-width: min(100%, 160px);
}
.bannerLead > svg {
  flex: 0 0 auto;
  margin-block: calc((1lh - var(--cipher-size-icon)) / 2);
  color: var(--cipher-accent-fg);
}
.bannerText {
  flex: 1;
  min-width: 0;
}
.steps {
  display: flex;
  flex-wrap: wrap;
  gap: 12px;
  padding: 0;
  margin: 0;
  list-style: none;
}
.step {
  display: flex;
  align-items: center;
  gap: 6px;
  font-family: var(--cipher-type-caption-font-family);
  font-size: var(--cipher-type-caption-font-size);
  line-height: var(--cipher-type-caption-line-height);
  font-weight: var(--cipher-type-caption-font-weight);
  letter-spacing: var(--cipher-type-caption-letter-spacing);
  color: var(--cipher-muted, var(--muted-foreground));
}
.step[data-current] {
  color: var(--cipher-ink, var(--foreground));
  font-weight: var(--cipher-type-title-sm-font-weight);
}
.stepNumber {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  width: 20px;
  height: 20px;
  border: 1px solid var(--cipher-line-soft, var(--border));
}
.step[data-current] .stepNumber {
  background: repeating-linear-gradient(
    135deg,
    var(--cipher-tint, var(--muted)) 0 2px,
    transparent 2px 4px
  );
  border-color: var(--cipher-ink, var(--foreground));
}
:global(.cipher) {
  --cipher-toast-bottom: var(--cipher-space-action-bar-offset);
}
:global(.cipher)[data-action-bar-reserve] {
  --cipher-toast-bottom: calc(
    var(--cipher-size-action-bar) + 2 * var(--cipher-space-action-bar-offset)
  );
}
.toastFixed {
  position: fixed;
  inset-inline-end: var(--cipher-space-16);
  bottom: var(--cipher-toast-bottom);
  z-index: 100;
  transition: bottom var(--cipher-duration-moderate) var(--cipher-ease-standard);
}
@media (prefers-reduced-motion: reduce) {
  .toastFixed {
    transition-duration: 0s;
  }
}
.toastTitle {
  font-family: var(--cipher-type-row-title-font-family);
  font-size: var(--cipher-type-row-title-font-size);
  line-height: var(--cipher-type-row-title-line-height);
  font-weight: var(--cipher-type-row-title-font-weight);
  letter-spacing: var(--cipher-type-row-title-letter-spacing);
}
.toastDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  margin-top: 2px;
  color: var(--cipher-text2, var(--muted-foreground));
}
.avatarStatus[data-status="ok"] {
  background: var(--cipher-ok);
}
.avatarStatus[data-status="warn"] {
  background: var(--cipher-warn);
}
.fieldLabels {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-field-label);
  min-width: 0;
}
.fieldLabelRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-4);
  min-width: 0;
}
.globHelp {
  display: flex;
  flex-direction: column;
  gap: var(--cipher-space-4);
}
.legendRow {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-4);
  width: 100%;
  min-width: 0;
  padding: 0;
}
.legendActions {
  display: flex;
  align-items: center;
  gap: var(--cipher-space-8);
  margin-inline-start: auto;
}
.fieldHelp {
  margin-block: calc(
    (var(--cipher-type-field-label-line-height) - var(--cipher-size-control-xs)) / 2
  );
  color: var(--cipher-muted);
}
.fieldDescription {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  margin: 0;
  color: var(--cipher-muted, var(--muted-foreground));
}
.fieldError {
  font-family: var(--cipher-type-small-font-family);
  font-size: var(--cipher-type-small-font-size);
  line-height: var(--cipher-type-small-line-height);
  font-weight: var(--cipher-type-small-font-weight);
  letter-spacing: var(--cipher-type-small-letter-spacing);
  display: flex;
  align-items: flex-start;
  gap: var(--cipher-space-6);
  margin: 0;
  color: var(--cipher-bad);
}
.fieldError > svg {
  flex: none;
  margin-block-start: calc((var(--cipher-type-small-line-height) - 14px) / 2);
}
.fieldErrorLines {
  display: flex;
  flex-direction: column;
